    /// little-endian, interleaved. The measurement reads it too, which is what
    /// makes "the gain is applied to what was measured" true by construction.
    static let floatMixSettings: [String: Any] = [
        AVFormatIDKey: Int(kAudioFormatLinearPCM),
        AVSampleRateKey: 48000,
        AVNumberOfChannelsKey: 2,
        AVLinearPCMBitDepthKey: 32,
        AVLinearPCMIsFloatKey: true,
        AVLinearPCMIsBigEndianKey: false,
        AVLinearPCMIsNonInterleaved: false,
    ]

    /// The master's release, fixed (AU-27): the number the gain's model reads.
    static let releaseSeconds = ExportLoudness.masterReleaseSeconds
    /// The most frames the limiter is handed at once.
    static let chunkFrames = 4096

    private static let sampleRate = 48_000
    private static let channels = 2

    /// 16 or 24: the depth handed to the encoder.
    let bits: Int
    /// The ceiling, linear: 10^(dBTP/20).
    let ceiling: Float
    /// The export range's start, the stamp of stream frame 0.
    let origin: CMTime
    /// The loudness gain (`ExportWriter.normalizeAudio`); 1 when not normalised.
    var linearGain: Float = 1
    /// False for a stem: the limiter is skipped, with its latency.
    let limits: Bool

    /// (`export_size::even_size`), so the size reported is the size the
    /// writer writes.
    ///
    /// It is asked of `avf_preset` and the codec rather than listed row by
    /// row, so a new AVFoundation row is even-sized until someone exempts
    /// it — the safe side, since 4:2:0 chroma needs it and a row that can
    /// keep an odd edge has to be measured doing so, as ProRes 4444 was
    /// (`ExporterWriter+Settings.swift`'s `encodedSize`). The audio-only
    /// rows answer true: they have no picture and go on reporting what
    /// `h264` reports. The two image rows answer false; their numbers are
    /// the fit (`fits_inside_size`), odd or not.
    pub(crate) fn even_sized(&self) -> bool {
        self.avf_preset.is_some() && self.codec != "prores4444"
    }

    /// True for a row whose bundled encoder has speeds, the rows
    /// `encoder_speed` applies to (spec §11 CX-12 (2), CX-16 (2)).
    pub(crate) fn takes_encoder_speed(&self) -> bool {
        self.writer.is_some_and(Writer::takes_speed)
    }

    /// True for the uncompressed audio rows, `audio_wav` and `audio_aiff`,
    /// the rows `audio_bits` applies to (spec §11 AU-29). ProRes's LPCM
    /// track keeps 16 bits; it is not an `lpcm` row.
    pub(crate) fn takes_audio_bits(&self) -> bool {
        self.codec == "lpcm"

        height = c.lenient(.height, 1080)
        fps = c.lenient(.fps, Fps.thirty)
        let range = try? c.nestedContainer(keyedBy: RangeKeys.self, forKey: .range)
        start = range?.lenient(.start, 0) ?? 0
        duration = range?.lenient(.duration, 0) ?? 0
        avPreset = c.lenient(.avPreset)
        fileType = c.lenient(.fileType)
        optimizeForNetwork = c.lenient(.optimizeForNetwork, true)
        videoBitrate = c.lenient(.videoBitrate)
        audioBitrate = c.lenient(.audioBitrate)
        loudnessLufs = c.lenient(.loudnessLufs)
        peakDbtp = c.lenient(.peakDbtp)
        // False is the safe default: only `prores_4444`, `hevc_alpha`,
        // `vp9_alpha_webm` and `apng` answer true, and a core that predates phase 7 does not emit
        // the key at all. Its silence UNDER-reports — that core has no
        // `prores_4444` row to describe, but its `apng` row wrote alpha then as it does
        // now — and under-reporting is the direction that cannot hurt: this
        // key only ADDS the footnote's "alpha" and ARMS
        // `ExportWriter.checkAlphaSurvivesTheSize`, so false promises less
        // than the file holds where true would promise more.
        alpha = c.lenient(.alpha, false)
        color = c.lenient(.color)
        writer = c.lenient(.writer)
        let speed: String? = c.lenient(.encoderSpeed)
        encoderSpeed = speed.flatMap(EncoderSpeed.init(rawValue:))
        audioBits = c.lenient(.audioBits)
        stems = c.lenient(.stems, [])
    }

    var renderSize: CGSize { CGSize(width: width, height: height) }
}

extension ExportSettings {
    /// Whether an encoding's sound is LPCM: the `lpcm` codec of the
    /// uncompressed audio rows, and every ProRes profile, which §7.8 pairs
    /// with uncompressed sound. The export sheet's fixed-rate rows
    /// (`ExportSheetController.Applies`) and the writer's audio settings
    /// (`ExportWriter.audioSettings`) both ask it.
    static func carriesLinearPCM(codec: String) -> Bool {
        let c = codec.lowercased()
        return c == "lpcm" || c.hasPrefix("prores")
    }
}

/// A bundled encoder's speed (spec §11 CX-2, CX-12 (2)): the core's word, the
/// sheet's name and SVT-AV1's preset.
enum EncoderSpeed: String, CaseIterable {
    case faster, balanced, smaller

    var menuName: String {
        switch self {
        case .faster: return "Faster"
        case .balanced: return "Balanced"
        case .smaller: return "Smaller file"
        }
    }

    var svtPreset: Int8 {
        switch self {
        case .faster: return 8
        case .balanced: return 6
        case .smaller: return 4
        }
    }
}

